async (page) => {
  await page.locator('input[slot=input]').fill('');
  await page.waitForTimeout(1000);
  return await page.evaluate(async () => {
    const g = document.querySelector('vaadin-grid');
    const seen = new Map();
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    g.scrollToIndex(0); await sleep(300);
    for (let i = 0; i < 200; i++) {
      g.shadowRoot.querySelectorAll('tbody tr').forEach(tr => {
        const t = [...tr.querySelectorAll('td')].map(td => td.innerText.trim());
        if (t[0] !== undefined) seen.set(t[2], t.join('|'));
      });
      const before = g.shadowRoot.querySelector('table').scrollTop;
      g.shadowRoot.querySelector('table').scrollTop += 400; await sleep(150);
      if (g.shadowRoot.querySelector('table').scrollTop === before) break;
    }
    return [...seen.values()].filter(s => s.includes('Laboratory'));
  });
}

