  await page.waitForTimeout(1000);
  return await page.evaluate(async () => {
    const g = document.querySelector('vaadin-grid');
    const sleep = ms => new Promise(r => setTimeout(r, ms));
    const seen = new Map();
    for (let i = 0; i < g.size; i += 5) {
      g.scrollToIndex(i); await sleep(120);
      g.shadowRoot.querySelectorAll('tbody tr').forEach(tr => {
        const t = [...tr.querySelectorAll('td')].map(td => {
          const c = td.querySelector('slot')?.assignedNodes()[0]; return c ? c.innerText.trim() : '';});
        if (t[2]) seen.set(t[2], t.join('|'));
      });
    }
    return {size: g.size, total: seen.size, left: [...seen.values()].filter(s => s.includes('Laboratory') && s.includes('Closed'))};
  });
}

